const crypto = require('crypto');
const accessKey = 'yCrnfHeNp7sKC5h3';
const secretKey = 'Em2sPDj0VaRGvnnY';
const baseUrl = 'https://metersphere.devops.moego.pet';
const timestamp = Date.now();
const uuid = crypto.randomUUID();
const comboxKey = `${accessKey}|${uuid}|${timestamp}`;
const key = Buffer.from(secretKey.slice(0, 16), 'utf-8');
const iv = Buffer.from(accessKey.slice(0, 16), 'utf-8');
const cipher = crypto.createCipheriv('aes-128-cbc', key, iv);
let encrypted = cipher.update(comboxKey, 'utf-8', 'base64');
encrypted += cipher.final('base64');
const input = $input.first().json;
const projectId = '20a78db9-19aa-11ee-a261-5a66b98c4036';
const page = input.page || 1;
const pageSize = input.page_size || 20;
const body = { projectId };
if (input.name) body.name = input.name;
if (input.node_id) body.nodeIds = [input.node_id];
return [{ json: { baseUrl, page, pageSize, body, headers: { 'Content-Type': 'application/json', 'ACCEPT': 'application/json', 'accessKey': accessKey, 'signature': encrypted } } }];

const response = $input.first().json;
if (!response.success) throw new Error(`MeterSphere API error: ${response.message}`);
const data = response.data || {};
const cases = (data.listObject || []).map(c => ({ id: c.id, num: c.num, name: c.name, priority: c.priority, status: c.status, review_status: c.reviewStatus, maintainer: c.maintainer, node_path: c.nodePath, type: c.type, tags: c.tags, create_time: c.createTime ? new Date(c.createTime).toISOString() : null, update_time: c.updateTime ? new Date(c.updateTime).toISOString() : null }));
return [{ json: { cases, total: data.itemCount || 0, page_count: data.pageCount || 0 } }];
